/*
 * KLEE Harness for ImageMagick ParseGeometry function
 *
 * This harness creates a symbolic geometry string and passes it to
 * ParseGeometry to exercise the geometry parsing code paths.
 */

#include "MagickCore/studio.h"
#include "MagickCore/MagickCore.h"
#include "MagickCore/geometry.h"
#include "MagickCore/memory_.h"
#include "MagickCore/string_.h"

#include <klee/klee.h>
#include <string.h>

#define MAX_GEOMETRY_LEN 32

int main(int argc, char **argv) {
    char geometry_str[MAX_GEOMETRY_LEN];

    /* Make the geometry string symbolic */
    klee_make_symbolic(geometry_str, sizeof(geometry_str), "geometry_str");

    /* Ensure the string is null-terminated */
    geometry_str[MAX_GEOMETRY_LEN - 1] = '\0';

    /* Parse the geometry string */
    GeometryInfo geometry_info;
    MagickStatusType flags = ParseGeometry(geometry_str, &geometry_info);

    /* Check for interesting conditions */
    if (flags != 0) {
        /* Some flags were set - check for specific combinations */
        if ((flags & PercentValue) && (flags & AspectValue)) {
            /* Both percent and aspect - interesting combination */
            klee_assert(geometry_info.rho >= 0);
        }
        if (flags & SeparatorValue) {
            /* Has 'x' separator */
            klee_assert(geometry_info.rho != geometry_info.sigma);
        }
    }

    return 0;
}
