{
  FuzzingDebugger
    debugger;

  int
    debug;

  wstring
    fileName;

  if (argc == 1)
    {
      wcerr << L"Filename must be specified as the first argument";
      return(1);
    }
  fileName=wstring(argv[1]);
  if (!debugger.load(fileName))
