/*
 * KLEE Harness for ImageMagick BMP/PNM image parsing
 * 
 * This harness creates a symbolic input buffer and passes it through
 * ImageMagick's BlobToImage function to exercise image parsing code paths.
 */

#include "MagickCore/studio.h"
#include "MagickCore/MagickCore.h"
#include "MagickCore/blob.h"
#include "MagickCore/constitute.h"
#include "MagickCore/exception.h"
#include "MagickCore/image.h"
#include "MagickCore/magick.h"
#include "MagickCore/memory_.h"
#include "MagickCore/string_.h"

#include <klee/klee.h>

#define MAX_BLOB_SIZE 256

/* External function declarations for coder registration */
extern size_t RegisterBMPImage(void);
extern size_t RegisterPNMImage(void);
extern void UnregisterBMPImage(void);
extern void UnregisterPNMImage(void);

int main(int argc, char **argv) {
    /* Symbolic input buffer */
    unsigned char input[MAX_BLOB_SIZE];

    /* Make the input buffer symbolic */
    klee_make_symbolic(input, sizeof(input), "image_input");

    /* Constrain the first 2 bytes to be BMP magic number for BMP format */
    /* BMP files start with "BM" (0x42, 0x4D) */
    /* Let's make the format selector symbolic too */
    int format_selector;
    klee_make_symbolic(&format_selector, sizeof(format_selector), "format_selector");

    /* Initialize ImageMagick */
    MagickCoreGenesis(NULL, MagickFalse);

    /* Register coders - we need at least BMP and PNM */
    RegisterBMPImage();
    RegisterPNMImage();

    /* Create image info */
    ExceptionInfo *exception = AcquireExceptionInfo();
    ImageInfo *image_info = AcquireImageInfo();

    if (image_info == NULL || exception == NULL) {
        if (exception) DestroyExceptionInfo(exception);
        if (image_info) DestroyImageInfo(image_info);
        MagickCoreGenesis(NULL, MagickFalse);
        return 0;
    }

    /* Set the magick format based on the format selector */
    if (format_selector == 0) {
        /* Try BMP format */
        CopyMagickString(image_info->magick, "BMP", MagickPathExtent);
        CopyMagickString(image_info->filename, "input.bmp", MagickPathExtent);
    } else {
        /* Try PNM format */
        CopyMagickString(image_info->magick, "PNM", MagickPathExtent);
        CopyMagickString(image_info->filename, "input.pnm", MagickPathExtent);
    }

    /* Call BlobToImage with the symbolic input */
    Image *image = BlobToImage(image_info, input, MAX_BLOB_SIZE, exception);

    /* Clean up */
    if (image != NULL) {
        DestroyImageList(image);
    }

    DestroyImageInfo(image_info);
    DestroyExceptionInfo(exception);

    UnregisterBMPImage();
    UnregisterPNMImage();

    MagickCoreTerminus();

    return 0;
}
HARNESS_EOF
echo "Harness created""}

