    /* Check for interesting edge cases in geometry parsing */
    if (flags & AllValues) {
        /* All values set - check for overflow */
        if (geometry_info.rho > 1e15 || geometry_info.sigma > 1e15) {
            klee_assert(0); /* Potential overflow */
        }
    }

    if (flags & (LessValue | GreaterValue)) {
        /* Both less and greater - contradictory flags */
        if ((flags & LessValue) && (flags & GreaterValue)) {
            klee_assert(0);
        }
